@import "./max.css";

@theme inline {
  --phi: calc((1 + sqrt(5)) / 2);
  --gwx: calc(var(--phi) - 1);
  --gnx: calc(1 - var(--gwx));
  --snx: calc(1 + var(--gnx));
  --swx: var(--phi);

  --font-sans: "max", ui-sans-serif, system-ui, sans-serif;
  --font-mono: "Source Code Pro", ui-monospace, monospace;

  --text-xs: calc(var(--text-md) * 0.98);
  --text-sm: calc(var(--text-md) * 0.99);
  --text-md: clamp(21px, calc(1dvw * var(--phi)), 28px);
  --text-core: var(--text-md);
  --text-lg: clamp(28px, calc(var(--text-md) * pow(var(--snx), 2)), 35px);
  --text-xl: clamp(35px, calc(var(--text-md) * pow(var(--snx), 3)), 42px);
  --text-2x: clamp(42px, calc(var(--text-md) * pow(var(--snx), 4)), 49px);
  --text-3x: clamp(49px, calc(var(--text-md) * pow(var(--snx), 5)), 56px);
  --text-4x: clamp(56px, calc(var(--text-md) * pow(var(--snx), 6)), 63px);
  --text-5x: clamp(63px, calc(var(--text-md) * pow(var(--snx), 7)), 70px);
  --text-6x: clamp(70px, calc(var(--text-md) * pow(var(--snx), 8)), 77px);
  --text-7x: clamp(77px, calc(var(--text-md) * pow(var(--snx), 9)), 84px);
  --text-8x: clamp(84px, calc(var(--text-md) * pow(var(--snx), 10)), 91px);
  --text-9x: clamp(91px, calc(var(--text-md) * pow(var(--snx), 11)), 98px);
  --line-height: clamp(1, var(--gnx), var(--gwx));

  --spacing-base: clamp(4px, calc(1rem * var(--gnx) / var(--swx)), 6px);
  --spacing-sm: clamp(2px, calc(var(--spacing-base) / var(--swx)), 4px);
  --spacing-xs: clamp(1px, calc(var(--spacing-sm) / var(--swx)), 3px);
  --spacing-md: clamp(var(--spacing-base), calc(var(--spacing-base) * var(--swx)), 28px);
  --spacing-lg: clamp(var(--spacing-md), calc(var(--spacing-md) * var(--swx)), 35px);
  --spacing-xl: clamp(var(--spacing-lg), calc(var(--spacing-lg) * var(--swx)), 42px);

  --color-background: var(--background);
  --color-foreground: var(--foreground);
  --color-card: var(--card);
  --color-card-foreground: var(--card-foreground);
  --color-popover: var(--popover);
  --color-popover-foreground: var(--popover-foreground);
  --color-primary: var(--primary);
  --color-primary-foreground: var(--primary-foreground);
  --color-secondary: var(--secondary);
  --color-secondary-foreground: var(--secondary-foreground);
  --color-muted: var(--muted);
  --color-muted-foreground: var(--muted-foreground);
  --color-accent: var(--accent);
  --color-accent-foreground: var(--accent-foreground);
  --color-destructive: var(--destructive);
  --color-border: var(--border);
  --color-input: var(--input);
  --color-ring: var(--ring);
  --color-success: var(--success);
  --color-warning: var(--warning);
  --radius-sm: calc(var(--radius) * 0.6);
  --radius-md: calc(var(--radius) * 0.8);
  --radius-lg: var(--radius);
  --radius-xl: calc(var(--radius) * 1.4);
  --radius-2xl: calc(var(--radius) * 1.8);
}

:root {
  color-scheme: light;
  --radius: 0.375rem;
  --background: #eff1f5;
  --foreground: #4c4f69;
  --card: #e6e9ef;
  --card-foreground: #4c4f69;
  --popover: #eff1f5;
  --popover-foreground: #4c4f69;
  --primary: #1e66f5;
  --primary-foreground: #eff1f5;
  --secondary: #ccd0da;
  --secondary-foreground: #4c4f69;
  --muted: #dce0e8;
  --muted-foreground: #6c6f85;
  --accent: #04a5e5;
  --accent-foreground: #eff1f5;
  --destructive: #d20f39;
  --border: #bcc0cc;
  --input: #ccd0da;
  --ring: #1e66f5;
  --success: #40a02b;
  --warning: #df8e1d;
}

.dark {
  color-scheme: dark;
  --background: #1e1e2e;
  --foreground: #cdd6f4;
  --card: #181825;
  --card-foreground: #cdd6f4;
  --popover: #181825;
  --popover-foreground: #cdd6f4;
  --primary: #89b4fa;
  --primary-foreground: #11111b;
  --secondary: #313244;
  --secondary-foreground: #cdd6f4;
  --muted: #313244;
  --muted-foreground: #a6adc8;
  --accent: #94e2d5;
  --accent-foreground: #11111b;
  --destructive: #f38ba8;
  --border: #45475a;
  --input: #313244;
  --ring: #89b4fa;
  --success: #a6e3a1;
  --warning: #f9e2af;
}
